library(shiny);

source("Q2A.R");

# Server
server <- function(input, output, session) {
  app_state <- reactiveValues(
    data = NULL,
    selected_patch = NULL,
    ready = FALSE,
    patch_order = NULL
  )

  # Validation for 7-digit student ID
  output$validation_message <- renderUI({
    student_id <- input$student_id
    if(is.na(student_id)) {
      return(div(style = "color: red; font-weight: bold;",
                 "Please enter a numeric Student ID"))
    }
    if(student_id < 1000000 || student_id > 9999999) {
      return(div(style = "color: red; font-weight: bold;",
                 "Please enter a valid 7-digit Student ID"))
    }
    return(NULL)
  })

  observeEvent(input$generate, {
    student_id <- input$student_id

    # Validate student ID
    if(is.na(student_id)) {
      showNotification("Please enter a numeric Student ID", type = "error")
      return()
    }
    if(student_id < 1000000 || student_id > 9999999) {
      showNotification("Please enter a valid 7-digit Student ID", type = "error")
      return()
    }

    tryCatch({
      app_state$data <- patch_data(student_id)
      set.seed(student_id)
      app_state$patch_order <- sample(1:12)
      app_state$selected_patch <- NULL
      app_state$ready <- TRUE
      showNotification("Patches generated successfully!", type = "message")
    }, error = function(e) {
      showNotification(paste("Error:", e$message), type = "error")
    })
  })

  output$status_info <- renderText({
    if (!app_state$ready) return("Click 'Generate Patches' to start")
    data <- app_state$data
    selected <- app_state$selected_patch
    if (is.null(data)) return("Error: No data available")
    status <- paste("Total patches:", length(data))
    if (!is.null(selected)) {
      insects <- data[[selected]]
      females <- sum(insects == 0)
      males <- sum(insects == 1)
      status <- paste(status, "\nSelected: Patch", selected, "(", females, "♀,", males, "♂)")
    }
    return(status)
  })

  output$patch_plot <- renderPlot({
    if (!app_state$ready || is.null(app_state$data) || is.null(app_state$patch_order)) {
      plot(1, 1, type = "n", xlim = c(0, 1), ylim = c(0, 1), 
           xlab = "", ylab = "", axes = FALSE, 
           main = "Insect Population Patches")
      text(0.5, 0.5, "Click 'Generate Patches' to start", cex = 1.8, col = "darkblue")
      return()
    }

    data <- app_state$data
    patch_order <- app_state$patch_order

    par(mar = c(1, 1, 3, 1), bg = "white")
    plot(1, 1, type = "n", xlim = c(0, 1), ylim = c(0, 1), 
         xlab = "", ylab = "", axes = FALSE, 
         main = "Click on any patch to sample the insects inside", cex.main = 1.3)

    for(position in 1:12) {
      patch_id <- patch_order[position]
      row <- ((position - 1) %/% 4) + 1
      col <- ((position - 1) %% 4) + 1
      x_pos <- 0.12 + (col - 1) * 0.22
      y_pos <- 0.85 - (row - 1) * 0.30
      insect_count <- length(data[[patch_id]])
      selected <- ifelse(is.null(app_state$selected_patch), FALSE, patch_id == app_state$selected_patch)
      draw_patch(x_pos, y_pos, insect_count, patch_id, selected)
    }
  })

  observeEvent(input$patch_click, {
    if (!app_state$ready || is.null(app_state$data) || is.null(app_state$patch_order)) return()
    x <- input$patch_click$x
    y <- input$patch_click$y

    col_idx <- NA
    row_idx <- NA

    for(col in 1:4) {
      col_center <- 0.12 + (col - 1) * 0.22
      if (abs(x - col_center) < 0.1) {
        col_idx <- col
        break
      }
    }

    for(row in 1:3) {
      row_center <- 0.85 - (row - 1) * 0.30
      if (abs(y - row_center) < 0.12) {
        row_idx <- row
        break
      }
    }

    if (is.na(col_idx) || is.na(row_idx)) return()
    position <- (row_idx - 1) * 4 + col_idx
    clicked_id <- app_state$patch_order[position]
    if (is.na(clicked_id) || clicked_id < 1 || clicked_id > 12) return()

    app_state$selected_patch <- clicked_id
    insects <- app_state$data[[clicked_id]]
    females <- sum(insects == 0)
    males <- sum(insects == 1)

    showModal(modalDialog(
      title = paste("Insects in Patch", clicked_id, "(", females, "♀,", males, "♂)"),
      plotOutput("insect_plot", height = "500px"),
      footer = actionButton("close_modal", "Close", class = "btn btn-primary"),
      size = "l",
      easyClose = TRUE
    ))
  })

  output$insect_plot <- renderPlot({
    if (is.null(app_state$selected_patch) || is.null(app_state$data)) {
      plot(1, 1, type = "n", xlim = c(0, 1), ylim = c(0, 1), 
           xlab = "", ylab = "", axes = FALSE)
      text(0.5, 0.5, "No data to display", cex = 1.5, col = "red")
      return()
    }

    patch_id <- app_state$selected_patch
    insects <- app_state$data[[patch_id]]

    par(mar = c(4, 2, 3, 2), bg = "white")
    plot(1, 1, type = "n", xlim = c(0, 1), ylim = c(0, 1), 
         xlab = "", ylab = "", axes = FALSE,
         main = paste("Insects in Patch", patch_id), cex.main = 1.5)

    n_insects <- length(insects)
    if (n_insects == 0) {
      text(0.5, 0.5, "No insects in this patch", cex = 1.8, col = "red")
      return()
    }

    grid_cols <- min(ceiling(sqrt(n_insects)), 5)
    grid_rows <- ceiling(n_insects / grid_cols)
    cell_width <- 0.9 / grid_cols
    cell_height <- 0.8 / grid_rows

    for(i in 1:n_insects) {
      row <- ((i - 1) %/% grid_cols) + 1
      col <- ((i - 1) %% grid_cols) + 1
      x_pos <- 0.05 + (col - 0.5) * cell_width
      y_pos <- 0.95 - (row - 0.5) * cell_height
      if(insects[i] == 0) draw_female_insect(x_pos, y_pos)
      else draw_male_insect(x_pos, y_pos)
    }

    legend(0.5, 0.1,
           legend = c("Female (square)", "Male (oval)"), 
           fill = c("lightblue", "lightgreen"),
           border = c("darkblue", "darkgreen"),
           title = "Insect Sex",
           cex = 1.1,
           xjust = 0.5,
           horiz = TRUE,
           bty = "n")
  })

  observeEvent(input$close_modal, {
    removeModal()
  })
}

library(shiny)

# Your new function
patch_data <- function(studentID, patch_number = 12){
  set.seed(studentID) 
  patches <- patch_number; 
  Ns      <- sort(sample(x = 10:26, size = patches, replace = FALSE));
  psize   <- 1:patches;
  beta    <- 0.4 / patches;
  srat    <- 0.1 + psize * beta;
  males   <- numeric(patches)  # Initialize males vector
  for(i in 1:patches){
    males[i] <- round(rnorm(n = 1, mean = srat[i], sd = 0.05) * Ns[i]);
  }
  males[males == 0] <- 1;
  females <- Ns - males;
  PATCH   <- list();
  for(i in 1:patches){
    PATCH[[i]] <- c(rep(x = 0, times = females[i]), 
                    rep(x = 1, times = males[i]));
  }
  return(PATCH);
}

# Function to draw a green oval patch - with consistent spots based on patch ID
draw_patch <- function(x, y, total_insects, patch_id, selected = FALSE) {
  base_size <- 0.03 + (total_insects / 40) * 0.07
  width <- base_size * 1.4
  height <- base_size * 1.1

  theta <- seq(0, 2 * pi, length.out = 100)
  x_oval <- x + width * cos(theta)
  y_oval <- y + height * sin(theta)

  green_colors <- c("#6B8E23", "#556B2F", "#2E8B57", "#228B22", "#006400", "#8FBC8F")
  patch_color <- green_colors[(patch_id %% length(green_colors)) + 1]

  polygon(x_oval, y_oval, col = patch_color, border = "#2F4F2F", lwd = 2)

  # Consistent spots based on patch ID - using fixed seed
  set.seed(patch_id)  # This ensures spots are always the same for each patch
  n_spots <- 3 + (patch_id %% 4)

  for(j in 1:n_spots) {
    spot_x <- x + runif(1, -width*0.6, width*0.6)
    spot_y <- y + runif(1, -height*0.6, height*0.6)
    spot_size <- runif(1, 0.005, 0.015)
    points(spot_x, spot_y, pch = 16, col = "#A2CD5A", cex = spot_size * 100)
  }

  if (!is.null(selected) && is.logical(selected) && selected) {
    symbols(x, y, circles = max(width, height) * 1.3, inches = FALSE, 
            add = TRUE, fg = "yellow", lwd = 4)
  }

  text(x, y - height - 0.05, 
       label = paste0("Patch ", patch_id, "\n", total_insects, " insects"), 
       cex = 1.0, col = "white", font = 2)
}

draw_female_insect <- function(x, y, size = 0.03) {
  rect(x - size * 0.8, y - size * 0.8, 
       x + size * 0.8, y + size * 0.8, 
       col = "lightblue", border = "darkblue", lwd = 1.5)

  for(i in -1:1) {
    segments(x - size * 0.8, y + i * size * 0.3, 
             x - size * 1.5, y + i * size * 0.3, 
             col = "darkblue", lwd = 1.5)
    segments(x + size * 0.8, y + i * size * 0.3, 
             x + size * 1.5, y + i * size * 0.3, 
             col = "darkblue", lwd = 1.5)
  }

  segments(x, y + size * 0.8, x - size * 0.5, y + size * 1.3, col = "darkblue", lwd = 1.5)
  segments(x, y + size * 0.8, x + size * 0.5, y + size * 1.3, col = "darkblue", lwd = 1.5)

  points(x - size * 0.3, y + size * 0.3, pch = 16, col = "black", cex = 0.6)
  points(x + size * 0.3, y + size * 0.3, pch = 16, col = "black", cex = 0.6)
}

draw_male_insect <- function(x, y, size = 0.03) {
  theta <- seq(0, 2 * pi, length.out = 50)
  x_oval <- x + size * 1.2 * cos(theta)
  y_oval <- y + size * 0.8 * sin(theta)
  polygon(x_oval, y_oval, col = "lightgreen", border = "darkgreen", lwd = 1.5)

  for(i in -1:1) {
    segments(x - size * 1.0, y + i * size * 0.3, 
             x - size * 1.7, y + i * size * 0.3, 
             col = "darkgreen", lwd = 1.5)
    segments(x + size * 1.0, y + i * size * 0.3, 
             x + size * 1.7, y + i * size * 0.3, 
             col = "darkgreen", lwd = 1.5)
  }

  segments(x, y + size * 0.8, x - size * 0.4, y + size * 1.2, col = "darkgreen", lwd = 1.5)
  segments(x, y + size * 0.8, x + size * 0.4, y + size * 1.2, col = "darkgreen", lwd = 1.5)

  points(x - size * 0.6, y + size * 0.3, pch = 16, col = "black", cex = 0.6)
  points(x + size * 0.6, y + size * 0.3, pch = 16, col = "black", cex = 0.6)
}
